import { api } from './authService';

const reservationService = {
  /** GET /reservations */
  getAll: async (params = {}) => {
    const { data } = await api.get('/reservations', { params });
    return data?.data ?? data;
  },

  getMyReservations: async () => {
    const { data } = await api.get('/reservations/my');
    return data?.data ?? data;
  },

  getById: async (id) => {
    const { data } = await api.get(`/reservations/${id}`);
    return data?.data ?? data;
  },

  /** POST /reservations
   * ✅ FIX : mapping snake_case → camelCase attendu par le backend
   *   client_id  → clientId
   *   room_id    → roomId
   *   check_in   → checkInDate
   *   check_out  → checkOutDate
   */
  create: async (payload) => {
    const mapped = {
      clientId:     Number(payload.client_id),
      roomId:       Number(payload.room_id),
      checkInDate:  payload.check_in,
      checkOutDate: payload.check_out,
      guests:       Number(payload.guests) || 1,
      notes:        payload.notes || '',
    };
    const { data } = await api.post('/reservations', mapped);
    return data?.data ?? data;
  },

  /** PUT /reservations/{id} */
  update: async (id, payload) => {
    const mapped = {
      clientId:     Number(payload.client_id),
      roomId:       Number(payload.room_id),
      checkInDate:  payload.check_in,
      checkOutDate: payload.check_out,
      guests:       Number(payload.guests) || 1,
      notes:        payload.notes || '',
    };
    if (payload.status) mapped.status = payload.status;
    const { data } = await api.put(`/reservations/${id}`, mapped);
    return data?.data ?? data;
  },

  cancel: async (id) => {
    const { data } = await api.patch(`/reservations/${id}/cancel`);
    return data?.data ?? data;
  },

  checkIn: async (id) => {
    const { data } = await api.patch(`/reservations/${id}/check-in`);
    return data?.data ?? data;
  },

  checkOut: async (id) => {
    const { data } = await api.patch(`/reservations/${id}/check-out`);
    return data?.data ?? data;
  },

  delete: async (id) => {
    const { data } = await api.delete(`/reservations/${id}`);
    return data?.data ?? data;
  },
};

export default reservationService;
